  function get(kind, variant) {
    const styles = shapes[kind];
    if (!styles) return null;
    const style = global.RacingVibesVehicleAssets?.getVariantStyle(kind, variant);
    return styles[style?.id] || styles[variant] || Object.values(styles)[0];
  }
  function apply(car) {
    const shape = get(car.kind, car.vehicleVariant);
    if (!shape) return false;
    const scale = car.length / shape.baseLength;
    // Collision edits must not retune the authored driving inertia.
    car.inertiaWidth ??= car.colliderWidth || car.width;
    car.inertiaLength ??= car.colliderLength || car.length;
    car.colliderWidth = shape.width * scale;
    car.colliderLength = shape.length * scale;
    car.colliderPolygons = shape.polygons.map(polygon => polygon.map(([x, y]) => ({x: x * scale, y: y * scale})));
    return true;
  }
  global.RacingVibesVehicleColliders = Object.freeze({get, apply, shapes});
